            "slot": "how",
            "label": "어떻게 작동하나",
            "body": "```도해\n층: 같은 이름이 여러 곳에 있으면 어느 것을 쓰나\n지역 :: 함수 안에서 만든 것. 함수가 끝나면 사라진다\n전역 :: 파일 어디서나 보인다. 오래 살아남는다\n내장 :: 언어가 미리 정해둔 이름들\n= 안쪽부터 찾아 나가므로 가까운 이름이 먼 이름을 가린다\n```\n\n변수가 보이는 범위를 스코프라고 한다. 함수 안에서 만든 이름은 그 함수 안에서만 보이고 함수가 끝나면 사라진다. 그래서 다른 함수에서 같은 이름을 써도 서로 부딪히지 않는다. 언어에 따라 중괄호 블록 단위로 더 좁게 잡는 선언 방식도 있다.\n\n이름이 값을 가리키는 방식에도 주의할 점이 있다. 숫자나 문자열 같은 것은 이름마다 값이 따로 있지만, 목록이나 객체는 이름이 그 덩어리를 가리키기만 한다. 그래서 한 목록을 두 이름에 담아두고 한쪽을 고치면 다른 쪽에서도 고쳐진 것이 보인다. 따로 두고 싶으면 복사본을 만들어야 한다.\n\n이름 짓는 관례도 언어마다 정해져 있다. 파이썬은 단어를 밑줄로 잇고 자바스크립트는 뒤 단어의 첫 글자를 올려 쓴다. 바뀌지 않을 값은 전부 대문자로 적어 구분한다."
