            "body": "```도해\n대조: DNS 가 없으면 인터넷은 어떻게 되나\nDNS 없이 || DNS 로\n주소 :: 숫자 12자리를 왼다 || 이름만 기억한다\n서버 이전 :: 접속 경로가 끊긴다 || 레코드만 고치면 된다\n장애 :: 그 서버가 죽으면 끝 || 다른 IP 로 즉시 돌린다\n= 사람은 이름을, 기계는 숫자를 쓴다. DNS 는 그 사이의 번역기다\n```\n\n숫자 주소를 외우게 하면 인터넷은 대중화되지 않았을 것이다. 서버를 옮길 때마다 사용자에게 새 주소를 공지해야 하고, 북마크는 전부 죽는다.\n\nDNS 는 **이름과 주소를 분리**해서 이 셋을 한꺼번에 해결한다. 이름은 그대로 두고 주소만 갈아끼우면 되기 때문이다."
