        "summary": "Firewall은 **정해둔 규칙에 따라 통신을 통과시키거나 막는 장치**다.",
        "definition": "오가는 패킷의 출발지와 목적지, 포트, 프로토콜을 보고 규칙과 맞춰본다. 규칙이 허락하지 않은 것은 목적지에 닿지 못한다.",
