            "slot": "how",
            "label": "어떻게 작동하나",
            "body": "가장 단순한 방화벽은 패킷 하나만 보고 판단한다. 그러면 우리 쪽에서 먼저 요청한 통신의 응답까지도 밖에서 들어온 낯선 접속처럼 보인다.\n\n상태 기반 방화벽은 지금 열려 있는 연결 목록을 들고 있다. 안에서 나간 요청을 기억해두고 그에 대한 응답이 돌아오면 같은 연결로 보고 통과시킨다. 밖에서 먼저 걸어온 연결만 새 접속으로 판단해 규칙을 적용한다.\n\n내용까지 보는 것은 다른 층의 일이다. 웹 포트로 들어오는 요청 자체는 통과시키되 그 안에 든 공격 문자열을 걸러내려면, 애플리케이션 계층에서 내용을 읽는 방화벽이 따로 필요하다."
