        "category": "네트워크",
        "summary": "HTTP는 **웹에서 요청과 응답을 주고받는 규칙**이다.",
        "definition": "브라우저가 \"이 파일 주세요\"라고 보내면 서버가 \"여기 있습니다\"라고 답한다. 그 편지의 양식을 정해둔 것이 HTTP다. 1991년에 나왔고 지금도 웹에서 오가는 거의 모든 것이 이 양식을 쓴다.",
