            "slot": "why",
            "label": "왜 필요한가",
            "body": "```도해\n대조: 공통 규칙이 없으면 웹은 어떻게 되나\nHTTP 없이 || HTTP 로\n접속 방식 :: 사이트마다 다르다 || 어디든 똑같다\n브라우저 :: 사이트별로 만든다 || 하나로 다 본다\n새 사이트 :: 지원될 때까지 못 봄 || 만들면 바로 열림\n= 웹이 퍼진 건 기술이 뛰어나서가 아니라 규칙이 하나였기 때문이다\n```\n\n초기 인터넷에는 파일을 주고받는 방법이 여럿 있었다. FTP, Gopher, 회사마다 만든 자체 방식. 브라우저를 만들려면 그걸 전부 지원해야 했고, 새로 생긴 방식은 지원이 붙을 때까지 아무도 못 봤다.\n\nHTTP는 양식 하나로 그 문제를 없앴다. 서버가 무엇으로 만들어졌든 HTTP로 답하기만 하면 세상의 모든 브라우저가 읽는다."
