            "slot": "why",
            "label": "왜 필요한가",
            "body": "```도해\n대조: 주소가 없으면 데이터는 어디로 가나\n주소 없이 || IP 주소로\n목적지 :: 정할 수 없다 || 하나로 정해짐\n중간 경로 :: 판단 근거 없음 || 앞부분으로 판단\n기기 여럿 :: 구분 못 함 || 각각 구분됨\n= 주소가 있어야 중간에서 어디로 넘길지를 정할 수 있다\n```\n\n인터넷에는 전체 길을 아는 중앙이 없다. 중간의 장비들은 주소의 앞부분만 보고 다음으로 넘길 곳을 정한다. 주소가 없으면 이 판단 자체가 성립하지 않는다.\n\n주소는 앞부분과 뒷부분으로 나뉜다. 앞부분은 어느 망인지, 뒷부분은 그 망 안의 몇 번째 기기인지를 가리킨다. 어디까지가 앞부분인지는 `192.168.1.0/24` 처럼 뒤에 붙는 숫자가 정한다."
