            "body": "```도해\n대조: 내부 업무 시스템을 인터넷에 그대로 두면 어떻게 되나\n공개망에 두면 || 인트라넷에\n접근 범위 :: 주소만 알면 됨 || 조직 안에서만\n공격 표면 :: 전 세계에 열림 || 내부로 한정\n인터넷 장애 :: 업무가 멈춘다 || 내부는 계속\n= 잠그는 게 아니라 닿을 수 있는 범위 자체를 줄이는 것이다\n```\n\n인사 기록이나 재무 자료를 다루는 시스템을 인터넷에 올려두면 로그인 화면 하나가 전 세계에 노출된다. 로그인을 잘 막아둬도 그 화면 자체를 향한 시도가 끊이지 않고, 취약점 하나가 발견되면 그날부터 전 세계가 그 문을 두드린다.\n\n인트라넷은 문을 잠그는 대신 문이 있는 자리를 줄인다. 밖에서는 주소를 알아도 닿지 않으므로, 밖에서 시도할 수 있는 일 자체가 사라진다."
