            "body": "사설 IP로 쓸 수 있는 대역은 정해져 있다. `10.0.0.0`부터 `10.255.255.255`까지, `172.16.0.0`부터 `172.31.255.255`까지, `192.168.0.0`부터 `192.168.255.255`까지 세 구간이다. 앞의 것은 규모가 큰 기업망이나 클라우드에서, 마지막 것은 가정과 소규모 사무실에서 주로 쓴다.\n\n주소를 바꾸는 일은 NAT가 한다. 내부에서 나가는 패킷의 출발지를 공인 IP로 고쳐 적으면서, 어느 내부 기기가 어느 포트를 썼는지 표에 기록해둔다. 응답이 돌아오면 그 표를 보고 원래 기기의 사설 IP로 되돌려 전달한다. 표가 있기 때문에 여러 기기가 공인 IP 하나를 같이 쓸 수 있다.\n\n공인 IP도 종류가 나뉜다. 접속할 때마다 바뀔 수 있는 유동 IP가 가정용 회선의 기본이고, 서버를 돌리려면 항상 같은 고정 IP가 필요하다. 클라우드에서는 서버에 붙였다 뗄 수 있는 고정 공인 IP를 따로 제공한다."
