            "body": "```도해\n대조: 조각이 사라지거나 뒤섞이면 어떻게 되나\nTCP 없이 || TCP 로\n빠진 조각 :: 그냥 비어 있다 || 다시 요청한다\n순서 뒤바뀜 :: 그대로 올라간다 || 맞춰서 올린다\n받는 속도 :: 넘치면 흘린다 || 상대에 맞춰 조절\n= 네트워크가 못 미더워도 위층은 안 미더운 줄 모르게 만드는 게 TCP의 일이다\n```\n\n인터넷의 아래층(IP)은 배달을 보장하지 않는다. 조각을 최선을 다해 보내볼 뿐이고, 라우터가 붐비면 버린다. 그 위에서 파일을 받으면 중간이 비거나 순서가 엉킨 채로 도착한다.\n\nTCP는 조각마다 번호를 붙이고 받았다는 신호를 주고받아 그 문제를 감춘다. 위층에 있는 HTTP는 네트워크가 불안정하다는 사실을 알 필요가 없어진다."
