        "definition": "프로토콜, 호스트, 경로, 물음표 뒤의 값까지 한 줄에 들어 있다. 브라우저는 이 한 줄을 쪼개서 어디로 접속할지와 무엇을 요청할지를 정한다.",
        "analogy": "택배 송장. 어느 도시, 어느 건물, 몇 호, 누구 앞인지가 한 장에 적혀 있어서 그것만 보고 배달한다.",
