            "label": "왜 필요한가",
            "body": "```도해\n대조: 자원을 가리키는 방식이 제각각이면 어떻게 되나\n표준이 없으면 || URL 로\n접근 방법 :: 서버마다 다름 || 같은 형식\n공유 :: 설명을 붙여야 함 || 한 줄 보내면 끝\n조건 전달 :: 방법이 따로 없음 || 물음표 뒤에\n= 형식을 하나로 정해두니 주소 한 줄이 곧 지시가 된다\n```\n\n주소 형식이 서버마다 다르면 링크를 걸 수도 없고 북마크할 수도 없다. 형식이 하나로 정해져 있으니 브라우저는 처음 보는 주소도 똑같이 처리할 수 있다.\n\n물음표 뒤에 조건을 붙일 수 있다는 점도 크다. 검색어와 정렬 방식이 주소에 들어 있으면 그 화면 상태를 그대로 남에게 보낼 수 있다."
