            "slot": "why",
            "label": "왜 필요한가",
            "body": "```도해\n대조: 공통 처리를 처리기마다 쓰면 어떻게 되나\n미들웨어 없이 || 미들웨어로\n인증 코드 :: 핸들러마다 || 한 곳에\n규칙 변경 :: 전부 찾아 고침 || 한 곳만 고침\n빠뜨림 :: 한 곳 빠지면 구멍 || 줄에 세우면 끝\n= 빠뜨릴 수 있는 자리를 아예 없애는 것이 이 구조의 값이다\n```\n\n로그인 확인을 처리기마다 쓰면 처리기가 늘어날 때마다 같은 코드가 늘어난다. 규칙이 바뀌면 전부 찾아 고쳐야 하고, 새로 만든 화면 하나에서 그걸 빠뜨리면 그곳만 뚫린 채 남는다.\n\n앞에 한 줄로 세워두면 그 자리가 사라진다. 보호할 경로는 전부 같은 줄을 지나고, 규칙은 한 곳에만 있다."
