            "body": "```도해\n대조: 출금은 됐는데 입금 전에 서버가 죽으면 어떻게 되나\n트랜잭션 없이 || 트랜잭션으로\n중간 실패 :: 돈이 사라진다 || 없던 일이 된다\n남의 중간 상태 :: 그대로 읽힌다 || 안 보인다\n복구 :: 손으로 맞춘다 || 자동으로 돌린다\n= 반쯤 진행된 상태가 밖에 남지 않게 하는 것이 목적이다\n```\n\n명령을 하나씩 따로 실행하면 그 사이에 끊길 수 있다. 출금은 반영됐는데 입금 전에 시스템이 멈추면 100원이 어디에도 없는 상태가 되고, 이걸 나중에 찾아 손으로 맞추는 일은 건수가 늘수록 불가능해진다.\n\n동시에 도는 다른 작업도 문제가 된다. 한쪽이 값을 고치는 중인데 아직 확정하지 않았을 때 다른 쪽이 그 값을 읽어가면, 나중에 앞쪽이 되돌려졌을 때 읽어간 쪽은 존재한 적 없는 값을 들고 있게 된다. 트랜잭션은 이 두 가지를 함께 다룬다."
