            "label": "왜 필요한가",
            "body": "```도해\n대조: 로컬에만 있는 API 는 무엇을 못 하나\n공개 전 || 공개 후\n접근 범위 :: 내 컴퓨터만 || 어디서나\n전달 방법 :: 파일로 넘김 || 주소로 호출\n내 PC 를 끄면 :: 바로 끊긴다 || 계속 떠 있다\n= 코드가 도는 것과 남이 쓸 수 있는 것은 다른 문제다\n```\n\nAPI 를 다 만들어도 팀원이 그 주소를 열면 아무것도 뜨지 않는다. `127.0.0.1` 은 \"이 컴퓨터\"를 가리키는 주소라, 각자의 컴퓨터에서 각자의 컴퓨터를 가리킬 뿐이다.\n\n외부 공개는 그 주소를 바깥에서 닿을 수 있는 것으로 바꾸는 작업이다. 주소가 생기면 그다음 문제가 따라온다. 누가 부르는지 확인해야 하고, 오가는 내용을 가려야 하고, 한 사람이 초당 수백 번 부르는 것을 막아야 한다."
