            "body": "```도해\n대조: 같은 값을 매번 DB 에서 읽으면 어떻게 되나\n캐시 없이 || 캐시로\n같은 조회 :: 매번 DB 까지 || 두 번째는 생략\nDB 부하 :: 요청 수만큼 || 미스일 때만\n응답 시간 :: 밀리초 단위 || 마이크로초 단위\n= 값이 안 바뀌는 동안에는 같은 일을 두 번 하지 않는다\n```\n\n공지사항이나 상품 정보처럼 잘 바뀌지 않는 값도 조회할 때마다 DB 까지 간다. 사용자가 천 명이면 같은 질의가 천 번 나가고, DB 는 매번 같은 답을 만들어 돌려준다. 느린 것도 문제지만 DB 가 먼저 한계에 닿는다.\n\n캐싱은 이 반복을 없앤다. 처음 한 번만 DB 에서 읽고 이후에는 메모리에서 꺼내니, 응답이 빨라지는 동시에 DB 가 받는 요청 수 자체가 줄어든다."
