            "body": "배스천은 인터넷에서 보이는 서버라 자동화된 접속 시도를 계속 받는다. 그래서 필요한 것만 남기고 나머지는 꺼둔다. 루트 로그인과 비밀번호 인증을 막고 공개키만 받는 것이 기본이고, 여기에 추가 인증을 더 걸기도 한다.\n\n내부 서버로 넘어갈 때는 배스천에 키를 올려두지 않는다. 키를 올리는 순간 그 서버 하나에 모든 사람의 키가 모이기 때문이다. 대신 SSH의 ProxyJump나 에이전트 포워딩으로, 키는 각자 PC에 둔 채 배스천을 통로로만 쓴다.\n\n```\n# ~/.ssh/config\nHost bastion\n  HostName 54.123.45.67\n  User ec2-user\n\nHost internal-db\n  HostName 10.0.1.50\n  User ubuntu\n  ProxyJump bastion\n```\n\n이렇게 적어두면 `ssh internal-db` 한 줄로 끝난다. 경유는 하지만 사람이 두 번 로그인하지는 않는다."
