            "body": "```도해\n대조: 서명해줄 기관이 없으면 어떻게 되나\n보증 없이 || CA 로\n상대 확인 :: 말만 믿는다 || 서명을 검증\n가짜 서버 :: 구분이 안 된다 || 경고가 뜬다\n암호화 :: 되긴 된다 || 상대까지 확인\n= 암호화는 내용만 가릴 뿐 상대가 누구인지는 말해주지 않는다\n```\n\n공격자가 진짜와 똑같이 생긴 서버를 세우고 사용자를 그쪽으로 끌어들이는 일은 어렵지 않다. 통신이 암호화돼 있어도 소용이 없다. 암호화는 오가는 내용을 가릴 뿐, 그 상대가 원래 가려던 곳인지는 말해주지 않기 때문이다.\n\nCA 는 이 자리에 제3자를 넣는다. 도메인의 주인만 인증서를 받을 수 있게 해두면, 가짜 서버는 그 도메인에 맞는 서명된 인증서를 구할 수 없다. 그래서 브라우저가 경고를 띄운다."
