        "definition": "브라우저는 어떤 사이트로 요청을 보낼 때 그 사이트의 쿠키를 자동으로 같이 보낸다. 공격자는 이 자동 첨부를 이용한다. 쿠키 값을 훔칠 필요 없이 요청만 만들어내면 서버는 본인이 한 일로 처리한다.",
