            "slot": "why",
            "label": "왜 필요한가",
            "body": "```도해\n대조: 비밀번호 하나만으로 지키면 어떻게 되나\n비밀번호만 || MFA 로\n유출되면 :: 바로 로그인됨 || 한 단계가 남음\n재사용 :: 다른 곳도 뚫림 || 그것만으론 안 됨\n알아채기 :: 모르고 지나감 || 시도 기록이 남음\n= 증거를 하나 더 두면 하나가 새어도 문이 열리지 않는다\n```\n\n비밀번호는 한 번 유출되면 그것으로 끝이다. 여러 사이트에서 같은 비밀번호를 쓰고 있으면 한 곳에서 샌 것이 다른 곳의 열쇠가 된다.\n\nMFA는 문을 두 개로 만든다. 비밀번호를 아는 것만으로는 통과가 안 되고, 두 번째 문을 열려면 본인이 실제로 갖고 있는 것이나 몸에 붙은 것이 필요하다."
