            "body": "```도해\n대조: 카페 와이파이에서 로그인하면 어떻게 되나\nHTTP 로 || HTTPS 로\n전송 내용 :: 그대로 읽힌다 || 가려져 있다\n중간에 끼어들기 :: 알 수 없다 || 인증서로 걸린다\n내용 변조 :: 티가 안 난다 || 검사에서 걸린다\n= 읽히는 것과 바꿔치기당하는 것을 함께 막는다\n```\n\n네트워크는 여러 장비를 거쳐 간다. 가려두지 않으면 그 사이 어디서든 내용을 볼 수 있고, 공용 와이파이에서는 특히 쉽다.\n\n더 큰 문제는 상대가 진짜인지 알 수 없다는 것이다. 가짜 서버가 중간에 앉아 양쪽 말을 옮기면 암호화만으로는 막지 못한다. 인증서가 이 자리를 맡아서, 그 도메인의 주인이 맞다고 제3자가 보증한 문서를 확인한다."
