            "body": "```도해\n대조: 내용을 그대로 두면 어떻게 되나\n암호화 없이 || 암호화해서\n가로챈 사람 :: 그대로 읽는다 || 뜻 없는 값\nDB 가 털리면 :: 내용이 다 나간다 || 값만 나간다\n저장 매체 분실 :: 꽂으면 열린다 || 못 연다\n= 새는 것을 막는 게 아니라 새어도 못 읽게 만드는 것이다\n```\n\n데이터는 오가는 도중에도 새고 쌓여 있는 동안에도 샌다. 공용 와이파이에서 오가는 통신은 같은 망에 있는 사람이 잡을 수 있고, DB가 통째로 유출되는 사고도 계속 일어난다.\n\n암호화는 새는 경로를 막지 않는다. 새더라도 가져간 쪽이 읽지 못하게 만든다. 그래서 접근 통제가 뚫린 다음에 남는 마지막 방어선이 된다."
