        "figure": "```도해\n흐름: 결제 한 건이 오갈 때 방화벽은 어디서 검사하나\n사용자 :: 웹서버의 443 번 포트로 요청한다\n방화벽 :: 인바운드 규칙에 443 이 있어 통과시킨다\n웹서버 :: 외부 결제 API 를 부른다\n방화벽 :: 아웃바운드 규칙을 보고 내보낸다\n방화벽 :: 그 응답은 나간 요청의 짝이라 그냥 통과\n< 웹서버 :: 결과를 사용자에게 돌려준다\n= 나간 요청의 응답은 인바운드 규칙이 없어도 들어온다\n```",
