            "body": "```도해\n대조: 업로드 파일을 서버 디스크에 두면 무엇이 달라지나\n서버 디스크에 || S3 에\n용량 :: 차면 늘려야 함 || 신경 안 씀\n서버 여러 대 :: 파일이 흩어짐 || 어디서든 같음\n서버 교체 :: 옮겨야 한다 || 그대로 남음\n= 파일을 서버 밖으로 빼면 서버는 언제든 버릴 수 있는 것이 된다\n```\n\n업로드 파일을 서버 디스크에 저장하면 그 서버가 파일을 들고 있게 된다. 트래픽이 늘어 서버를 두 대로 늘리면 한쪽에 올린 파일이 다른 쪽에서는 안 보이고, 서버를 새로 띄우면 그동안 쌓인 것을 옮겨야 한다. 디스크가 차면 그때마다 늘려야 한다.\n\nS3는 파일을 서버 밖으로 뺀다. 서버는 파일을 들고 있지 않고 주소만 안다. 서버가 몇 대든 같은 파일을 보고, 서버를 지우고 새로 띄워도 파일은 그 자리에 남는다."
