            "body": "서브넷이 공개인지 비공개인지는 붙어 있는 라우팅 규칙이 정한다. 인터넷 게이트웨이로 나가는 길이 적혀 있으면 공개 구획이고, 그 길이 없거나 NAT를 거치게 되어 있으면 비공개 구획이다. 서브넷 자체에 공개라는 표시가 붙는 게 아니다.\n\n주소 범위는 CIDR 표기로 적는다. `/24`는 앞의 24비트가 고정이라는 뜻이고 남는 8비트로 256개 주소가 나온다. 숫자가 클수록 좁은 범위다.\n\n```도해\n층: 클라우드 네트워크는 어떤 단위로 겹쳐 있나\n네트워크 :: 10.0.0.0/16 전체 주소 범위\n가용 영역 :: 물리적으로 떨어진 데이터센터\n서브넷 :: 한 가용 영역 안의 주소 구획\n자원 :: 그 구획 안에서 주소를 하나 받는 서버\n= 서브넷 하나는 반드시 가용 영역 하나 안에 들어간다\n```\n\n서브넷이 가용 영역 하나에 묶인다는 점이 설계를 정한다. 한 곳이 멈춰도 서비스가 이어지려면 같은 역할의 구획을 여러 가용 영역에 하나씩 만들어야 한다."
