            "body": "```도해\n대조: 고객사가 천 곳으로 늘면 무엇이 달라지나\n고객마다 따로 || 하나를 나눠 쓰면\n서버 :: 고객 수만큼 || 한 벌로 끝난다\n업데이트 :: 천 번 배포한다 || 한 번 배포한다\n자원 활용 :: 20~40% || 70~90%\n= 하나를 나눠 쓰면 비용은 줄고 격리 책임은 커진다\n```\n\n고객마다 서버와 DB와 애플리케이션을 따로 세우면 자원이 남는다. 어떤 고객은 CPU를 10%만 쓰면서 서버 한 대를 통째로 차지한다. 고객이 늘수록 이 낭비도 같이 늘어난다.\n\n배포는 더 큰 문제다. 버그 하나를 고쳐도 고객 수만큼 배포해야 하고, 고객이 천 곳이면 관리가 불가능해진다. 애플리케이션 한 벌이 모든 테넌트를 받도록 만들면 한 번 배포로 전부에 적용되고, 새 고객을 붙이는 비용도 거의 없어진다."
