            "slot": "why",
            "label": "왜 필요한가",
            "body": "```도해\n대조: 설정값을 코드에 그대로 적으면 어떻게 되나\n코드에 적으면 || 환경 변수로\n비밀번호 :: 저장소에 남음 || 코드에 없음\n환경 변경 :: 코드를 고침 || 값만 바꿈\n배포 :: 환경마다 빌드 || 하나로 배포\n= 코드와 설정을 떼어놓으면 같은 빌드를 어디에나 올릴 수 있다\n```\n\n비밀번호나 API 키를 코드에 적으면 저장소에 그대로 들어간다. 공개 저장소에 실수로 올라가는 것도 문제지만, 지운 뒤에도 커밋 기록에 남아 있다는 점이 더 성가시다.\n\n설정이 코드 안에 있으면 환경마다 다른 코드를 배포해야 한다는 문제도 생긴다. 개발용으로 빌드한 것과 운영용으로 빌드한 것이 달라지면, 개발에서 되던 것이 운영에서 안 되는 이유를 찾기 어려워진다."
