            "body": "```도해\n대조: 회사 내부 규정을 물으면 어떻게 되나\nRAG 없이 || RAG 로\n모르는 것 :: 그럴듯하게 지음 || 문서에서 찾는다\n최신 정보 :: 학습 시점까지만 || 문서 고치면 끝\n출처 :: 댈 수 없다 || 조항까지 댄다\n= 기억으로 답하던 것을 찾아 읽고 답하는 것으로 바꾼다\n```\n\n일반 LLM 에 \"우리 회사 육아휴직 기간은?\"이라고 물으면 \"보통 1년입니다\" 같은 답이 돌아온다. 학습할 때 본 적 없는 사내 문서인데도 모른다고 말하는 대신 그럴듯한 값을 지어낸다. 지난달에 바뀐 가격을 물어도 사정은 같다.\n\nRAG 는 답을 만들기 전에 검색을 한 번 끼워 넣는다. 취업규칙에서 육아휴직 대목을 먼저 찾아 프롬프트에 붙이고, 그 안에서만 답하라고 시킨다. 규정이 바뀌면 문서만 갈아 끼우고 모델은 그대로 둔다."
